1	package org.springframework.samples.petclinic.util;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Scores an owner's membership points. The score starts at 0 and gains {@link #EMAIL_POINTS} when an
7	 * email address is present, {@link #UNIQUE_NAME_POINTS} when the owner has a unique name
8	 * (namesakeCount is zero), {@link #HOUSEHOLD_POINTS} for a household of {@link #HOUSEHOLD_MIN} or more
9	 * members, and {@link #TENURE_POINTS} when the owner's {@link Tenure tenure} reaches
10	 * {@link #TENURE_FISCAL_YEARS} elapsed fiscal year. Because a newly created owner has zero tenure, a
11	 * new owner never earns the tenure points. The points band into a {@link MembershipLevel membership
12	 * level}.
13	 */
14	public final class MembershipPoints {
15	
16	    /** Points awarded when an email address is present. */
17	    public static final int EMAIL_POINTS = 2;
18	
19	    /** Points awarded when the owner has a unique name (namesakeCount is zero). */
20	    public static final int UNIQUE_NAME_POINTS = 1;
21	
22	    /** Points awarded for a household of {@link #HOUSEHOLD_MIN} or more members. */
23	    public static final int HOUSEHOLD_POINTS = 2;
24	
25	    /** Points awarded when tenure reaches {@link #TENURE_FISCAL_YEARS} elapsed fiscal year. */
26	    public static final int TENURE_POINTS = 3;
27	
28	    /** Household size at or above which the household points are awarded. */
29	    public static final int HOUSEHOLD_MIN = 3;
30	
31	    /** Elapsed fiscal years at or beyond which the tenure points are awarded. */
32	    public static final int TENURE_FISCAL_YEARS = 1;
33	
34	    private MembershipPoints() {
35	    }
36	
37	    /** The membership points for {@code owner}, or {@code null} when the owner is {@code null}. */
38	    public static Integer of(Owner owner) {
39	        if (owner == null) {
40	            return null;
41	        }
42	        int points = 0;
43	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
44	            points += EMAIL_POINTS;
45	        }
46	        Integer namesakeCount = owner.getNamesakeCount();
47	        if (namesakeCount != null && namesakeCount == 0) {
48	            points += UNIQUE_NAME_POINTS;
49	        }
50	        Integer householdSize = owner.getHouseholdSize();
51	        if (householdSize != null && householdSize >= HOUSEHOLD_MIN) {
52	            points += HOUSEHOLD_POINTS;
53	        }
54	        if (Tenure.fiscalYears(owner) >= TENURE_FISCAL_YEARS) {
55	            points += TENURE_POINTS;
56	        }
57	        return points;
58	    }
59	}
