9	/**
10	 * Captures the ceiling on the new owner's membership level: one above the highest
11	 * {@link MembershipLevel membership level} among the owners already sharing its
12	 * {@link HouseholdNormalizer#id(String, String) household id} (same last name and postcode). Runs
13	 * before {@link SaveOwner}, so the count is taken over existing household members only; with no
14	 * existing member no cap applies and the ceiling stays {@code null}. The stored cap is applied when
15	 * the owner's level is read (see {@code OwnerMapper#membershipLevel}). Mutates the built
16	 * {@link Owner} in place.
17	 */
18	public class CapMembershipLevel {
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
21	        String householdId = owner.getHouseholdId();
22	        Integer maxLevel = null;
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (HouseholdNormalizer.belongsTo(existing, householdId)) {
25	                Integer level = MembershipLevel.forPoints(MembershipPoints.of(existing));
26	                if (level != null && (maxLevel == null || level > maxLevel)) {
27	                    maxLevel = level;
28	                }
29	            }
30	        }
31	        owner.setMembershipLevelCap(maxLevel == null ? null : maxLevel + 1);
32	    }
33	}
