27	/**
28	 * Maps Owner & OwnerDto using Mapstruct
29	 */
30	@Mapper(uses = PetMapper.class)
31	public interface OwnerMapper {
32	
33	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
34	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
35	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
36	    @Mapping(target = "initials", expression = "java(initials(owner))")
37	    @Mapping(target = "locality", expression = "java(locality(owner))")
38	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
39	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
40	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
41	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
42	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
43	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
44	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
45	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
46	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
47	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
48	    OwnerDto toOwnerDto(Owner owner);
49	
50	    /** The canonical API path of the owner: '/api/owners/' followed by the owner's id. */
51	    default String selfLink(Owner owner) {
52	        return owner == null || owner.getId() == null ? null : "/api/owners/" + owner.getId();
53	    }
54	
55	    /** The owner's name formatted as 'LastName, FirstName'. */
56	    default String displayName(Owner owner) {
57	        return owner == null ? null : owner.getLastName() + ", " + owner.getFirstName();
58	    }
59	
60	    /**
61	     * The owner's salutation: the honorific title followed by a space and the last name (e.g.
62	     * 'DR who'), or just the last name when no title is given.
63	     */
64	    default String salutation(Owner owner) {
65	        if (owner == null) {
66	            return null;
67	        }
68	        String title = owner.getTitle();
69	        return title == null || title.isBlank() ? owner.getLastName() : title + " " + owner.getLastName();
70	    }
71	
72	    /**
73	     * The canonical region taken from the owner's region-and-hash identity: the REGION portion of the
74	     * customerCode (see {@link CustomerCode}). Falls back to deriving the region directly from the
75	     * city and postcode (see {@link Locality}) for an owner that has no customerCode yet.
76	     */
77	    default String locality(Owner owner) {
78	        if (owner == null) {
79	            return null;
80	        }
81	        String region = CustomerCode.regionOf(owner.getCustomerCode());
82	        return region != null ? region : Locality.of(owner.getCity(), owner.getPostcode());
83	    }
84	
85	    /**
86	     * The owner's IANA timezone (see {@link RegionTimezone}), derived from the owner's
87	     * {@link #locality(Owner) locality} (region): NSW->Australia/Sydney, VIC->Australia/Melbourne,
88	     * QLD->Australia/Brisbane. {@code null} when the region has no timezone.
89	     */
90	    default String timezone(Owner owner) {
91	        return owner == null ? null : RegionTimezone.of(locality(owner));
92	    }
93	
94	    /** The upper-cased first letters of the first and last name, e.g. 'J.S.'. */
95	    default String initials(Owner owner) {
96	        return owner == null ? null
97	            : Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
98	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
99	    }
100	
101	    /**
102	     * The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the
103	     * last two digits of the registration date's year, e.g. 'NSW-1A2B3C4D-M26'.
104	     */
105	    default String membershipNumber(Owner owner) {
106	        return MembershipNumber.of(owner);
107	    }
108	
109	    /**
110	     * The owner's fiscal year (see {@link FiscalYear}) as 'FY&lt;YY&gt;', where YY is the last two
111	     * digits of the fiscal year (starting 1 July) of the business-day-adjusted registration date.
112	     * {@code null} when the owner or its registration date is {@code null}.
113	     */
114	    default String fiscalYear(Owner owner) {
115	        return owner == null || owner.getRegistrationDate() == null ? null
116	            : FiscalYear.label(owner.getRegistrationDate());
117	    }
118	
119	    /**
120	     * The owner's check digit (see {@link CheckDigit}): the Luhn check digit over the digits of the
121	     * customer code.
122	     */
123	    default Integer checkDigit(Owner owner) {
124	        return owner == null ? null : CheckDigit.of(owner.getCustomerCode());
125	    }
126	
127	    /**
128	     * The owner's membership points (see {@link MembershipPoints}): a score that starts at 0 and
129	     * gains 2 for a present email address, 1 for a unique name (namesakeCount is zero), 2 for a
130	     * household of 3 or more and 3 for tenure over a year.
131	     */
132	    default Integer membershipPoints(Owner owner) {
133	        return MembershipPoints.of(owner);
134	    }
135	
136	    /**
137	     * The owner's membership level (see {@link MembershipLevel}): the {@link #membershipPoints(Owner)
138	     * membership points} banded into a number from 1 to 4 (1 for 0-1 points, 2 for 2-3, 3 for 4-5,
139	     * 4 for 6 or more), then held down to the owner's household ceiling
140	     * ({@link Owner#getMembershipLevelCap()}) captured at creation. With no ceiling the banded level
141	     * stands.
142	     */
143	    default Integer membershipLevel(Owner owner) {
144	        Integer level = MembershipLevel.forPoints(MembershipPoints.of(owner));
145	        Integer cap = owner == null ? null : owner.getMembershipLevelCap();
146	        return level != null && cap != null ? Math.min(level, cap) : level;
147	    }
148	
149	    /**
150	     * The owner's preferred contact channel (see {@link ContactPreference}): 'EMAIL' when an email
151	     * address is present, otherwise 'PHONE'.
152	     */
153	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
154	        ContactPreference preference = ContactPreference.of(owner);
155	        return preference == null ? null : OwnerDto.ContactPreferenceEnum.valueOf(preference.name());
156	    }
157	
158	    /**
159	     * The owner's derived identity key (see {@link IdentityKey}): the canonical telephone, email and
160	     * household id joined by '|'. A read-only summary of the owner's contact identity; duplicate
161	     * detection itself keys off the household id.
162	     */
163	    default String identityKey(Owner owner) {
164	        return owner == null ? null : IdentityKey.forOwner(owner);
165	    }
166	
167	    /**
168	     * The owner's age band (see {@link AgeBand}): 'MINOR' under 18, 'ADULT' from 18 to 64 and
169	     * 'SENIOR' at 65 or older, measured from the birth date against the registration date, or
170	     * {@code null} when no birth date was given.
171	     */
172	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
173	        AgeBand band = AgeBand.of(owner);
174	        return band == null ? null : OwnerDto.AgeBandEnum.valueOf(band.name());
175	    }
176	
177	    /**
178	     * The stored E.164 telephone formatted for humans (see
179	     * {@link TelephoneNormalizer#toDisplay(String)}): the country code, a space, then the national
180	     * digits grouped in threes, e.g. '+61 412 345 678'. The raw telephone stays in E.164 form.
181	     */
182	    default String telephoneDisplay(Owner owner) {
183	        return owner == null ? null : TelephoneNormalizer.toDisplay(owner.getTelephone());
184	    }
185	
