6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * The duplicate block: a request is a hard duplicate when an existing active owner has the same
11	 * {@link IdentityKey identity key} (SHA-256 over the canonical telephone, email and {@link
12	 * org.springframework.samples.petclinic.util.Soundex Soundex} of the last name), and is rejected with
13	 * a 409 via {@link DuplicateIdentityException}. Because the telephone is part of the key, two owners
14	 * with the same last name and postcode but a <em>different</em> telephone are not a hard duplicate:
15	 * the request passes this block and is instead marked for follow-up by {@link FlagPossibleDuplicate}
16	 * and held to its household level ceiling by {@link CapMembershipLevel}. Setting {@code
17	 * sharesHousehold} bypasses this block outright, so the new owner is created as a declared household
18	 * member. The email-domain blocklist ({@link ValidateEmailDomain}) is applied earlier in the
19	 * pipeline, so a blocked address is already rejected before this step. Soft-deleted owners are
20	 * ignored, so a match that has since been deleted no longer blocks the create.
21	 */
22	public class EnsureUniqueIdentity {
23	
24	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository)
25	            throws DuplicateIdentityException {
26	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
27	            return;
28	        }
29	        String identityKey = IdentityKey.forOwner(owner);
30	        for (Owner existing : ownerRepository.findAll()) {
31	            if (existing.isActive() && identityKey.equals(IdentityKey.forOwner(existing))) {
32	                throw new DuplicateIdentityException(identityKey);
33	            }
34	        }
35	    }
36	}
