1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.util.Sha256;
5	
6	/**
7	 * Canonical household identity shared by the create pipeline. A household is keyed on
8	 * <em>last name plus postcode</em>: the last name is compared case-insensitively with runs of
9	 * whitespace collapsed to a single space and outer whitespace trimmed, and the postcode is compared
10	 * verbatim. Owners with equal keys are the same household and therefore share the same
11	 * {@link #id(String, String) household id}, which is a pure, stable function of those two fields — so
12	 * it is stamped on every owner at creation ({@link AssignHousehold}) rather than looked up.
13	 *
14	 * <p>The id feeds the rules that key off the household: the household-size count
15	 * ({@link CountHousehold}) and the membership-level ceiling ({@link CapMembershipLevel}) decide
16	 * membership with {@link #belongsTo(Owner, String)}. (Duplicate detection and the possible-duplicate
17	 * flag instead key off the {@link IdentityKey}.) Not a pipeline step, so it is free to expose plain
18	 * helpers.
19	 */
20	public final class HouseholdNormalizer {
21	
22	    private HouseholdNormalizer() {
23	    }
24	
25	    /**
26	     * The stable household identifier for an owner: the first 12 hex characters of the SHA-256 of the
27	     * household {@link #key(String, String) key}. Owners with equal keys share the same id, and the id
28	     * never changes for a given (last name, postcode), so it can be recomputed rather than stored.
29	     */
30	    public static String id(String lastName, String postcode) {
31	        return Sha256.prefix(key(lastName, postcode), 12);
32	    }
33	
34	    /**
35	     * Builds the canonical household key: the normalized last name and the postcode joined by '|'.
36	     * Two owners belong to the same household when their keys are equal. Either field may be
37	     * {@code null}, which normalizes to an empty token.
38	     */
39	    public static String key(String lastName, String postcode) {
40	        return normalizeName(lastName) + "|" + orEmpty(postcode);
41	    }
42	
43	    /**
44	     * Whether {@code owner} belongs to the household identified by {@code householdId}, i.e. its own
45	     * (last name, postcode) hashes to that id. {@code false} when {@code householdId} is {@code null}.
46	     */
47	    public static boolean belongsTo(Owner owner, String householdId) {
48	        return householdId != null && householdId.equals(id(owner.getLastName(), owner.getPostcode()));
49	    }
50	
51	    /** Lower-cases and collapses whitespace to single spaces, trimming the ends; {@code null} → "". */
52	    private static String normalizeName(String value) {
53	        if (value == null) {
54	            return "";
55	        }
56	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
57	    }
58	
59	    private static String orEmpty(String value) {
60	        return value == null ? "" : value;
61	    }
62	}
